    else:
        (height, width, channels) = (shape[-2], shape[-1], shape[-3])
    pad_height = int(float(width * target_height) / target_width)
    pad_height = max(height, pad_height)
    pad_width = int(float(height * target_width) / target_height)
    pad_width = max(width, pad_width)
    img_box_hstart = int(float(pad_height - height) / 2)
    img_box_wstart = int(float(pad_width - width) / 2)
    if data_format == 'channels_last':
        if img_box_hstart > 0:
            if len(images.shape) == 4:
                padded_img = jnp.concatenate([jnp.ones((batch_size, img_box_hstart, width, channels), dtype=images.dtype) * fill_value, images, jnp.ones((batch_size, img_box_hstart, width, channels), dtype=images.dtype) * fill_value], axis=1)
            else:
                padded_img = jnp.concatenate([jnp.ones((img_box_hstart, width, channels), dtype=images.dtype) * fill_value, images, jnp.ones((img_box_hstart, width, channels), dtype=images.dtype) * fill_value], axis=0)
        elif img_box_wstart > 0:
            if len(images.shape) == 4:
                padded_img = jnp.concatenate([jnp.ones((batch_size, height, img_box_wstart, channels), dtype=images.dtype) * fill_value, images, jnp.ones((batch_size, height, img_box_wstart, channels), dtype=images.dtype) * fill_value], axis=2)
            else:
                padded_img = jnp.concatenate([jnp.ones((height, img_box_wstart, channels), dtype=images.dtype) * fill_value, images, jnp.ones((height, img_box_wstart, channels), dtype=images.dtype) * fill_value], axis=1)
        else:
            padded_img = images
    elif img_box_hstart > 0:
        if len(images.shape) == 4:
            padded_img = jnp.concatenate([jnp.ones((batch_size, channels, img_box_hstart, width)) * fill_value, images, jnp.ones((batch_size, channels, img_box_hstart, width)) * fill_value], axis=2)
        else:
            padded_img = jnp.concatenate([jnp.ones((channels, img_box_hstart, width)) * fill_value, images, jnp.ones((channels, img_box_hstart, width)) * fill_value], axis=1)
    elif img_box_wstart > 0:
        if len(images.shape) == 4:
            padded_img = jnp.concatenate([jnp.ones((batch_size, channels, height, img_box_wstart)) * fill_value, images, jnp.ones((batch_size, channels, height, img_box_wstart)) * fill_value], axis=3)
        else:
            padded_img = jnp.concatenate([jnp.ones((channels, height, img_box_wstart)) * fill_value, images, jnp.ones((channels, height, img_box_wstart)) * fill_value], axis=2)
    else:
        padded_img = images
    images = padded_img
return jax.image.resize(images, size, method=interpolation, antialias=antialias)

